0005: {% set summary = summary|default({}) %}{% set targets = targets|default([]) %}{% set ai_notes = ai_notes|default([]) %}{% set risk_counts = risk_counts|default({}) %}{% set target_url = safe_url_for('strategic_performance.target_list', fallback='/performans/stratejik/hedefler') if safe_url_for is defined else '/performans/stratejik/hedefler' %}{% set analysis_url = safe_url_for('strategic_performance.ai_kpi_analysis', fallback='/performans/stratejik/ai-kpi-analiz') if safe_url_for is defined else '/performans/stratejik/ai-kpi-analiz' %}
0006: <div class="page-shell sp3x-page"><section class="sp3x-hero sp3x-glass"><div><p class="sp3x-eyebrow">Stratejik Performans</p><h1>KPI Dashboardu</h1><p class="sp3x-subtitle">Kurumsal hedefleri, risk alanlarını, gerçekleşme oranlarını ve yönetici takip ihtiyacını tek ekranda gösteren karar destek görünümü.</p></div><div class="sp3x-actions"><a class="sp3x-btn sp3x-btn-light" href="{{ target_url }}">Hedef Yönetimi</a><a class="sp3x-btn sp3x-btn-primary" href="{{ analysis_url }}">Analiz Merkezi</a></div></section><section class="sp3x-grid-4"><article class="sp3x-metric"><span>Toplam Hedef</span><strong>{{ summary.get('total_targets', 0) }}</strong><small>Aktif izlenen kayıt</small></article><article class="sp3x-metric"><span>Ortalama Gerçekleşme</span><strong>%{{ summary.get('average_completion', 0) }}</strong><small>Tüm hedef ortalaması</small></article><article class="sp3x-metric"><span>Ağırlıklı Başarı</span><strong>%{{ summary.get('weighted_completion', 0) }}</strong><small>Öncelik etkisiyle hesaplanır</small></article><article class="sp3x-metric"><span>Riskli Hedef</span><strong>{{ summary.get('risk_targets', 0) }}</strong><small>Yönetici takibi önerilir</small></article></section><section class="sp3x-two"><article class="sp3x-card sp3x-glass"><div class="sp3x-section-head"><div><p class="sp3x-eyebrow">Risk Dağılımı</p><h2>Hedef sağlığı</h2></div><span class="sp3x-badge">Canlı Özet</span></div><div class="sp3x-insight-list"><div class="sp3x-insight"><strong>Düşük Risk:</strong> {{ risk_counts.get('Düşük', 0) }} hedef dengeli ilerliyor.</div><div class="sp3x-insight"><strong>Orta Risk:</strong> {{ risk_counts.get('Orta', 0) }} hedef için dönem içi takip önerilir.</div><div class="sp3x-insight"><strong>Yüksek Risk:</strong> {{ risk_counts.get('Yüksek', 0) }} hedef yönetici dikkati gerektiriyor.</div></div></article><article class="sp3x-card sp3x-glass"><div class="sp3x-section-head"><div><p class="sp3x-eyebrow">Karar Destek</p><h2>Yönetici özeti</h2></div><span class="sp3x-badge">AI Hazır</span></div><div class="sp3x-insight-list">{% for note in ai_notes %}<div class="sp3x-insight">{{ note }}</div>{% else %}<div class="sp3x-insight">KPI/Hedef kayıtları oluştuğunda yöneticiye yardımcı özetler gösterilecektir.</div><div class="sp3x-insight">Risk, gerçekleşme ve ağırlık bilgisi birlikte değerlendirilir.</div>{% endfor %}</div></article></section><section class="sp3x-card sp3x-glass"><div class="sp3x-section-head"><div><p class="sp3x-eyebrow">Canlı İzleme</p><h2>Öne çıkan KPI ve hedefler</h2></div><span class="sp3x-badge">{{ data_note|default('Canlı veri uyumlu') }}</span></div>{% if targets %}<div class="sp3x-table-wrap"><table class="sp3x-table"><thead><tr><th>Kod</th><th>Hedef</th><th>Sahip</th><th>Gerçekleşme</th><th>Risk</th><th>Durum</th></tr></thead><tbody>{% for item in targets %}<tr><td><strong>{{ item.code }}</strong></td><td>{{ item.name }}</td><td>{{ item.owner_name }}</td><td><div class="sp3x-progress"><span style="width: {{ item.completion_rate if item.completion_rate <= 100 else 100 }}%"></span></div><small>%{{ item.completion_rate }}</small></td><td><span class="sp3x-pill">{{ item.risk_level }}</span></td><td>{{ item.status }}</td></tr>{% endfor %}</tbody></table></div>{% else %}<div class="sp3x-empty"><div class="sp3x-empty-icon"><i class="fa-solid fa-bullseye"></i></div><h3>Henüz aktif KPI kaydı bulunmuyor</h3><p>Hedef kayıtları oluşturulduğunda bu ekran gerçekleşme, risk ve yönetici özetlerini otomatik gösterecek.</p><a class="sp3x-btn sp3x-btn-primary" href="{{ target_url }}">Hedef Yönetimine Git</a></div>{% endif %}</section></div>
