0006: <div class="page-shell sp3x-page"><section class="sp3x-hero sp3x-glass"><div><p class="sp3x-eyebrow">Stratejik Performans</p><h1>KPI ve Hedef Yönetimi</h1><p class="sp3x-subtitle">Kurumsal, birim ve personel hedeflerini tek merkezden izleyin; gerçekleşme, risk ve durum bilgisini anlaşılır şekilde takip edin.</p></div><div class="sp3x-actions">{% if can_manage %}<a class="sp3x-btn sp3x-btn-primary" href="{{ create_url }}">Yeni KPI / Hedef Oluştur</a>{% endif %}<a class="sp3x-btn sp3x-btn-light" href="{{ dashboard_url }}">KPI Dashboardu</a></div></section><section class="sp3x-grid-4"><article class="sp3x-metric"><span>Toplam Kayıt</span><strong>{{ total_count }}</strong><small>Listelenen KPI ve hedef</small></article><article class="sp3x-metric"><span>Aktif İzleme</span><strong>{{ total_count }}</strong><small>Canlı takip ekranında görünür</small></article><article class="sp3x-metric"><span>Risk Takibi</span><strong>Var</strong><small>Gerçekleşme oranına göre okunur</small></article><article class="sp3x-metric"><span>Yönetim Bağlantısı</span><strong>Hazır</strong><small>Dashboard ile entegre</small></article></section><section class="sp3x-card sp3x-glass"><div class="sp3x-section-head"><div><p class="sp3x-eyebrow">Liste Kontrolü</p><h2>Hedef kayıtları</h2></div><span class="sp3x-badge">Canlı kullanım görünümü</span></div><div class="sp3x-toolbar"><div class="sp3x-search"><i class="fa-solid fa-magnifying-glass"></i><input id="sp3xSearch" type="search" placeholder="KPI kodu, hedef adı veya birim içinde ara"></div><select class="sp3x-select" id="sp3xRisk"><option value="">Tüm riskler</option><option value="düşük">Düşük risk</option><option value="orta">Orta risk</option><option value="yüksek">Yüksek risk</option></select><select class="sp3x-select" id="sp3xStatus"><option value="">Tüm durumlar</option><option value="aktif">Aktif</option><option value="takip">Takipte</option><option value="risk">Riskli</option></select></div></section><section class="sp3x-card sp3x-glass">{% if items %}<div class="sp3x-table-wrap"><table class="sp3x-table" id="sp3xTable"><thead><tr><th>Kod</th><th>Hedef</th><th>Kapsam</th><th>Gerçekleşme</th><th>Risk</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>{% for item in items %}{% set item_id = item.id|default(item.get('id', loop.index) if item.get is defined else loop.index) %}{% set code = item.code|default(item.target_code|default(item.get('code', item.get('target_code', 'KPI-' ~ item_id)) if item.get is defined else 'KPI-' ~ item_id)) %}{% set name = item.name|default(item.title|default(item.target_name|default(item.get('name', item.get('title', item.get('target_name', 'Adsız Hedef'))) if item.get is defined else 'Adsız Hedef'))) %}{% set scope = item.scope|default(item.owner_name|default(item.unit_name|default(item.get('scope', item.get('owner_name', item.get('unit_name', 'Kurumsal'))) if item.get is defined else 'Kurumsal'))) %}{% set completion = item.completion_rate|default(item.progress|default(item.get('completion_rate', item.get('progress', 0)) if item.get is defined else 0)) %}{% set risk = item.risk_level|default(item.risk|default(item.get('risk_level', item.get('risk', 'Düşük')) if item.get is defined else 'Düşük')) %}{% set status = item.status|default(item.durum|default(item.get('status', item.get('durum', 'Takipte')) if item.get is defined else 'Takipte')) %}{% set edit_url = safe_url_for('strategic_performance.target_edit', target_id=item_id, fallback='/performans/stratejik/hedefler') if safe_url_for is defined else '/performans/stratejik/hedefler' %}<tr data-search="{{ (code ~ ' ' ~ name ~ ' ' ~ scope)|lower }}" data-risk="{{ risk|lower }}" data-status="{{ status|lower }}"><td><strong>{{ code }}</strong></td><td>{{ name }}<br><small class="sp3x-muted">Hedef kartı</small></td><td>{{ scope }}</td><td><div class="sp3x-progress"><span style="width: {{ completion if completion <= 100 else 100 }}%"></span></div><small>%{{ completion }}</small></td><td><span class="sp3x-pill">{{ risk }}</span></td><td>{{ status }}</td><td>{% if can_manage %}<a class="sp3x-mini-link" href="{{ edit_url }}">Düzenle</a>{% else %}<span class="sp3x-muted">Görüntüle</span>{% endif %}</td></tr>{% endfor %}</tbody></table></div>{% else %}<div class="sp3x-empty"><div class="sp3x-empty-icon"><i class="fa-solid fa-list-check"></i></div><h3>Henüz KPI veya hedef kaydı bulunmuyor</h3><p>İlk hedef kartları oluşturulduğunda liste, risk ve gerçekleşme bilgileri otomatik olarak gösterilecek.</p>{% if can_manage %}<a class="sp3x-btn sp3x-btn-primary" href="{{ create_url }}">İlk Hedefi Oluştur</a>{% endif %}</div>{% endif %}</section></div><script>document.addEventListener("DOMContentLoaded",function(){const s=document.getElementById("sp3xSearch"),r=document.getElementById("sp3xRisk"),st=document.getElementById("sp3xStatus"),t=document.getElementById("sp3xTable");if(!t)return;function f(){const q=(s&&s.value||"").toLowerCase().trim(),rv=(r&&r.value||"").toLowerCase().trim(),sv=(st&&st.value||"").toLowerCase().trim();t.querySelectorAll("tbody tr").forEach(function(row){const h=row.getAttribute("data-search")||"",rr=row.getAttribute("data-risk")||"",rs=row.getAttribute("data-status")||"";row.style.display=(!q||h.includes(q))&&(!rv||rr.includes(rv))&&(!sv||rs.includes(sv))?"":"none";});}if(s)s.addEventListener("input",f);if(r)r.addEventListener("change",f);if(st)st.addEventListener("change",f);});</script>
