0007: <div class="workflow-page"><section class="wf-hero"><div class="wf-kicker">BYS360 · Belgenet Benzeri Süreç İzleme</div><h1 class="wf-title">İş Akış Takip Paneli</h1><p class="wf-subtitle">Performans süreçleri, 70 altı Başkan onayları, geciken adımlar ve modüller arası süreçler tek yönetim ekranında izlenir.</p><div class="wf-actions"><form method="post" action="{{ url_for('main.workflow_sync_performance') }}"><input type="hidden" name="csrf_token" value="{{ csrf_token() if csrf_token is defined else '' }}"><button class="wf-btn wf-btn-primary" type="submit">Performans Akışlarını Tara</button></form><a class="wf-btn" href="{{ url_for('main.workflow_delays') }}">Gecikenler</a><a class="wf-btn" href="{{ url_for('main.workflow_notifications') }}">Bildirim Kuyruğu</a><a class="wf-btn" href="{{ url_for('main.workflow_president_approvals') }}">Başkan Onayları</a><a class="wf-btn" href="{{ url_for('main.workflow_modules_dashboard') }}">Modül Akışları</a></div></section>{% if created_count or created_timeline_count %}<div class="alert alert-success rounded-4 border-0 shadow-sm">Yeni oluşturulan Başkan onayı: {{ created_count or 0 }} · Yeni timeline: {{ created_timeline_count or 0 }}</div>{% endif %}<div class="wf-grid"><div class="wf-card wf-metric"><div class="label">Aktif Süreç</div><div class="num">{{ stats.active_count or 0 }}</div></div><div class="wf-card wf-metric"><div class="label">Tamamlanan</div><div class="num">{{ stats.completed_count or 0 }}</div></div><div class="wf-card wf-metric danger"><div class="label">Başkan Onayı / Kritik</div><div class="num">{{ stats.high_active_count or 0 }}</div></div><div class="wf-card wf-metric"><div class="label">Geciken Süreç</div><div class="num">{{ stats.delayed_count or 0 }}</div></div></div><div class="wf-card"><div class="wf-card-h"><strong>Süreç Listesi</strong><div class="btn-group btn-group-sm"><a class="btn btn-outline-secondary {% if status=='ACTIVE' %}active{% endif %}" href="{{ url_for('main.workflow_dashboard', status='ACTIVE') }}">Aktif</a><a class="btn btn-outline-secondary {% if status=='COMPLETED' %}active{% endif %}" href="{{ url_for('main.workflow_dashboard', status='COMPLETED') }}">Tamamlanan</a><a class="btn btn-outline-secondary {% if status=='ALL' %}active{% endif %}" href="{{ url_for('main.workflow_dashboard', status='ALL') }}">Tümü</a></div></div><div class="wf-table-wrap"><table class="wf-table"><thead><tr><th>Süreç</th><th>Personel</th><th>Mevcut Adım</th><th>Durum</th><th>Öncelik</th><th>Gecikme</th><th></th></tr></thead><tbody>{% for r in rows %}<tr><td><strong>{{ r.title }}</strong><div class="wf-mini">{{ r.module }} · {{ r.period_title or '-' }}</div></td><td>{{ r.employee_name or '-' }}</td><td><span class="wf-pill wf-pill-blue">{{ r.current_step_name or '-' }}</span></td><td><span class="wf-pill wf-pill-gray">{{ r.status }}</span></td><td>{% if r.priority in ['HIGH','CRITICAL'] %}<span class="wf-pill wf-pill-red">{{ r.priority }}</span>{% else %}<span class="wf-pill wf-pill-gray">{{ r.priority or '-' }}</span>{% endif %}</td><td>{% if r.delay_state == 'CRITICAL' %}<span class="wf-pill wf-pill-red">Gecikmiş</span>{% elif r.delay_state == 'WARNING' %}<span class="wf-pill wf-pill-yellow">Yaklaşıyor</span>{% else %}<span class="wf-pill wf-pill-green">Normal</span>{% endif %}</td><td class="text-end"><a class="wf-btn" href="{{ url_for('main.workflow_timeline', workflow_id=r.id or r.workflow_id) }}">Timeline</a></td></tr>{% else %}<tr><td colspan="7" class="wf-empty">Henüz iş akışı kaydı yok.</td></tr>{% endfor %}</tbody></table></div></div></div>
